  /* ── Skill kit ─────────────────────────────────── */
  var KIT = {};
  function htmlEsc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function redrawKit() {
    var box = el('kit_box');
    var open = {};
    qall('.kit-cat').forEach(function (c, i) { open[i] = c.classList.contains('collapsed'); });
    var h = '';
    SKILLS.forEach(function (cat, ci) {
