    setTimeout(function () {
      try {
        var w = window.parent || window;
        var ta = w.document.getElementById('send_textarea') ||
                 w.document.querySelector('textarea.chat-input,#textareaAutosize,textarea');
        if (ta) {
          var desc = Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype, 'value');
          if (desc && desc.set) desc.set.call(ta, payload); else ta.value = payload;
          ta.dispatchEvent(new Event('input', { bubbles: true }));
